  [39002] = {
    pieces_common_share_sentence = {
      common_config_value = "#Mr Love: Queen's Choice#The moment when fireworks bloomed into eternity, it read ''Be with me''."
    },
    pieces_icon_id = {common_config_value = "119119"},
    pieces_mal_share_sentence_xm = {
      common_config_value = "In the blooming of fireworks, you were reflected in his eyes of admiration. :Another sound of the fireworks was the long-lasting echoes of the few words he whispered in your ear. :At the end of the long path reflected in the light of fireworks, he reached out his hand to you."
    },
    pieces_male_main_panel_sentence_bq = {
      common_config_value = "At the top of the ferris wheel, fireworks silently went out and the whole world was in his control. :When he raised his eyes and looked into the crowd, you always shone uniquely and brightly. :When the fireworks went out in the sky, he firmly held your hand and walked towards the future."
    },
    pieces_male_main_panel_sentence_lzy = {
      common_config_value = "When the sparks bloomed at its peak, he pressed the pause button for the world and waited for your answer. :Beauty lied in numerous moments that formed a stream of discrete fragments of you and him. :You shone so brightly that his eyes could not help but be fixed on you."
    },
    pieces_male_main_panel_sentence_xm = {
      common_config_value = "In the blooming of fireworks, you were reflected in his eyes of admiration. :Another sound of the fireworks was the long-lasting echoes of the few words he whispered in your ear. :At the end of the long path reflected in the light of fireworks, he reached out his hand to you."
    },
    pieces_male_main_panel_sentence_zql = {
      common_config_value = "As fireworks lit up the sky, his murmurs revealed the most silent concern. :In the lonely nights when innumerable beautiful fireworks bloomed, he always thought that you should be by his side. :Fireworks resembled an appealing screen that quietly caught your eyes and took away all your breath."
    },
    pieces_male_share_sentence_bq = {
      common_config_value = "At the top of the ferris wheel, fireworks silently went out and the whole world was in his control. :When he raised his eyes and looked into the crowd, you always shone uniquely and brightly. :When the fireworks went out in the sky, he firmly held your hand and walked towards the future."
    },
    pieces_male_share_sentence_lzy = {
      common_config_value = "When the sparks bloomed at its peak, he pressed the pause button for the world and waited for your answer. :Beauty lied in numerous moments that formed a stream of discrete fragments of you and him. :You shone so brightly that his eyes could not help but be fixed on you."
    },
    pieces_male_share_sentence_zql = {
      common_config_value = "As fireworks lit up the sky, his murmurs revealed the most silent concern. :In the lonely nights when innumerable beautiful fireworks bloomed, he always thought that you should be by his side. :Fireworks resembled an appealing screen that quietly caught your eyes and took away all your breath."
    },
