  [39003] = {
    pieces_common_share_sentence = {
      common_config_value = "#恋与制作人#耳畔的倾诉，是专属于春日的告白。"
    },
    pieces_drop_k1 = {common_config_value = "1"},
    pieces_drop_k2 = {common_config_value = "2"},
    pieces_drop_need_cards = {
      common_config_value = "61020:62020:63020:64020"
    },
    pieces_icon_id = {common_config_value = "119193"},
    pieces_mal_share_sentence_xm = {
      common_config_value = "早春的第一枝新绿舒展的叶脉里，有他为你写的诗。:藏着今年所有好运的那只饺子，他已经悄悄放进了你的碗里。:你的名字是一句最简单的咒语，足以让花开至永不凋谢的黎明。"
    },
    pieces_male_main_panel_sentence_bq = {
      common_config_value = "你是躁动的浮世中最醒目的路标，他只要看见你就有了家的方向。:被珍守在领地内的你，是他最柔软也最坚强的信仰。:他是一座毫不设防的城池，只等你以爱为名占领。"
    },
    pieces_male_main_panel_sentence_lx = {
      common_config_value = "他心中有片雷鸣缠绕的森林，只有你能一无所虑穿行。:欠你的那些秘密，总有一天他会一并还给你。:他仿似骤来的雨，将心意瞒住，却希望你能记住。"
    },
    pieces_male_main_panel_sentence_lzy = {
      common_config_value = "他对你心意的长度，不需要以秒计时、以年定义。:无需承诺，他的一言一行，就是最强有力的誓言。:他将岁月揉碎，加上蜜糖，掺进了每一个送给你的布丁里。"
    },
    pieces_male_main_panel_sentence_xm = {
      common_config_value = "早春的第一枝新绿舒展的叶脉里，有他为你写的诗。:藏着今年所有好运的那只饺子，他已经悄悄放进了你的碗里。:你的名字是一句最简单的咒语，足以让花开至永不凋谢的黎明。"
    },
    pieces_male_main_panel_sentence_zql = {
      common_config_value = "闭上眼睛，他就在今晚最香甜的梦中等你。:只有你能懂他奇奇怪怪，只有他会陪你可可爱爱。:是你眼瞳里明亮的火焰，点燃了他的未来每一个绚烂瞬间。"
    },
