  [39004] = {
    pieces_common_share_sentence = {
      common_config_value = "#恋与制作人#给自己放个假，和他一起静静享受这一份悠闲和温暖。"
    },
    pieces_drop_k1 = {common_config_value = "0"},
    pieces_drop_k2 = {common_config_value = "0"},
    pieces_drop_need_cards = {common_config_value = "0"},
    pieces_icon_id = {common_config_value = "119224"},
    pieces_mal_share_sentence_xm = {
      common_config_value = "最柔软的言语，为你带来闲暇时的一夜好梦。:当生活慢下来时，一切美好都被仔细倾听。:甜蜜从交缠的手指开始，蔓延发散。"
    },
    pieces_male_main_panel_sentence_bq = {
      common_config_value = "再耀眼的色彩，也比不上他看向你时眼中的星芒。:不用言语，不消协商，你们的步调总是一致，你们的默契无人能及。:他永远是你步履疲乏时，最及时的充电站。"
    },
    pieces_male_main_panel_sentence_lx = {
      common_config_value = "看似漫不经心的相处中，也许暗藏着他没说出口的另一个秘密。:用一杯可乐的时间忘记烦恼，享受眼下的甜。:漫步街巷时，长板滑过的声音一定不会缺席。"
    },
    pieces_male_main_panel_sentence_lzy = {
      common_config_value = "喧闹背后，在只属于两个人的时间，和最真实的彼此相拥。:繁忙的工作和生活中，总有能让你们携手驻步的空隙。:轻巧的脚步，交织奏响属于两个人的乐章。"
    },
    pieces_male_main_panel_sentence_xm = {
      common_config_value = "最柔软的言语，为你带来闲暇时的一夜好梦。:当生活慢下来时，一切美好都被仔细倾听。:甜蜜从交缠的手指开始，蔓延发散。"
    },
    pieces_male_main_panel_sentence_zql = {
      common_config_value = "把自己安心交给他，平日积攒的疲惫，由他为你抚平。:将与他每一次的经历与回忆，收纳进属于两个人的空间。:驻步在他的温度中，休息到下个明天再携手启程。"
    },
