  [39005] = {
    pieces_common_share_sentence = {
      common_config_value = "You speak each other's unspoken language and share a tacit understanding.#MrLove"
    },
    pieces_drop_k1 = {common_config_value = "0"},
    pieces_drop_k2 = {common_config_value = "0"},
    pieces_drop_need_cards = {common_config_value = "0"},
    pieces_icon_id = {common_config_value = "119226"},
    pieces_mal_share_sentence_xm = {
      common_config_value = "Moonlight flows like water, and his thoughts are hidden about everywhere.:Hidden feelings surge and swell, a romance that is his alone.:Every look and laugh from you makes his heart bloom in a thousand blossoms."
    },
    pieces_male_main_panel_sentence_bq = {
      common_config_value = "Cherished words longing to be said become the protection of a vast and mighty wind.:He's turned the name over in his heart a million times, and now he swears a lifelong oath upon it.:Those childhood moments you haven't looked back on are for him feelings to last an eternity."
    },
    pieces_male_main_panel_sentence_lx = {
      common_config_value = "The forecast says today is sunny, and after you accept his date invitation, it starts to rain while the sun's still out.:The most extreme sport in the world is you trying to contain your racing heart in his presence.:Sounds The carbonation bubbles dance on the tongue, but your name is the most refreshing sound of all."
    },
    pieces_male_main_panel_sentence_lzy = {
      common_config_value = "All his weariness is soothed away by the nighttime lamp you light.:One by one, you find everything he's hidden in his heart, carefully collecting it.:The ornate latte art is a metaphor for his feelings, its sweetness changing from second to second."
    },
    pieces_male_main_panel_sentence_xm = {
