  [39006] = {
    pieces_common_share_sentence = {
      common_config_value = "Bring a dash of cool to this blazing hot summer with him!#mrlovemobile"
    },
    pieces_drop_k1 = {common_config_value = "0"},
    pieces_drop_k2 = {common_config_value = "0"},
    pieces_drop_need_cards = {common_config_value = "0"},
    pieces_icon_id = {common_config_value = "119265"},
    pieces_mal_share_sentence_xm = {
      common_config_value = "His breath next to your ears made you more restless than the heat.:The most beautiful dream he had was to explore the ocean with you.:The soothing smell of tea softened even the heat."
    },
    pieces_male_main_panel_sentence_bq = {
      common_config_value = "He handed you a popsicle that cooled down the summer.:You love talking about summer and the soft breeze that's always around you.:He pointed out the Summer Triangle for you. Now you will think of him whenever you look up during summer nights."
    },
    pieces_male_main_panel_sentence_lx = {
      common_config_value = "He had other ways to cool things down when the power went out.:You managed to cool down with a coke, but he brought up the heat with his eyes.:The sudden rainfall was a nice surprise tonight."
    },
    pieces_male_main_panel_sentence_lzy = {
      common_config_value = "Thanks to the air conditioner, you sat close to each other on the sofa, sometimes unintentionally touching each other.:The sun warmed his eyes and showed the tenderness deep within that’s reserved for you only.:The moment when you caught him in the water, you heard splashing and each other's heartbeat."
    },
    pieces_male_main_panel_sentence_xm = {
