  [39007] = {
    pieces_common_share_sentence = {
      common_config_value = "The beauty of the moon and flowers... he only wants to share it with you. #MrLoveMobile"
    },
    pieces_drop_k1 = {common_config_value = "0"},
    pieces_drop_k2 = {common_config_value = "0"},
    pieces_drop_need_cards = {common_config_value = "0"},
    pieces_icon_id = {common_config_value = "119287"},
    pieces_mal_share_sentence_xm = {
      common_config_value = "The moon waxes and wanes, but your heart is always full with him by your side.: The water reflects not only the bright moon but also the silhouettes of you two, leaning against each other.: In the sky, a full moon. In his embrace, you sit, listening to his whispers of love into your ear."
    },
    pieces_male_main_panel_sentence_bq = {
      common_config_value = "The streetlamps light up the meandering path. Without having to even look, you know he's right by your side.: There's no need to pray to the moon, for you know that you're destined to spend the rest of your life together.: The osmanthus leaves dancing in the wind bring romantic emotions from the moon palace."
    },
    pieces_male_main_panel_sentence_lx = {
      common_config_value = "Your plans for the holiday are all ruined, for now you shall spend the night with him.: He takes a bite of the moon cake in your hand and gives you a sweeter one.: He approaches on his skateboard, eyes lingering on nothing except the moon and you."
    },
    pieces_male_main_panel_sentence_lzy = {
      common_config_value = "Enjoy a cup of osmanthus wine with him... Now your lips taste like him too, sweet and fragrant.: In the shop, the mooncakes are sweet, the fruit wine is sweet, and the shop owner's breaths... also sweet.: The definition of reunion is you and I, together."
    },
    pieces_male_main_panel_sentence_xm = {
      common_config_value = "The moon waxes and wanes, but your heart is always full with him by your side.: The water reflects not only the bright moon but also the silhouettes of you two, leaning against each other.: In the sky, a full moon. In his embrace, you sit, listening to his whispers of love into your ear."
    },
    pieces_male_main_panel_sentence_zql = {
      common_config_value = "You're running under the moonlit skies, hand in his, golden tresses dancing in the wind, melting into the night.: He sneaks up behind you, leans over and plants an autumn-flower-like kiss on the corner of your lips.: You spend the night together. He helps you prepare dinner, making the meal an especially sweet one."
