  [39008] = {
    pieces_common_share_sentence = {
      common_config_value = "#恋与制作人#岁岁年年，倾听他暗藏心底的告白。"
    },
    pieces_drop_k1 = {common_config_value = "0"},
    pieces_drop_k2 = {common_config_value = "0"},
    pieces_drop_need_cards = {common_config_value = "0"},
    pieces_icon_id = {common_config_value = "119413"},
    pieces_mal_share_sentence_xm = {
      common_config_value = "跨越新年只要一瞬，而一瞬却因你被切分成许多微小的永恒。:如果清晨醒来发现你在，他会如同跌进一场轻柔的梦里。:电话里传来一阵嘈杂，他从中听见你呼喊他的姓名，淡淡笑了。"
    },
    pieces_male_main_panel_sentence_bq = {
      common_config_value = "世界被爱转动，驻足在他望向你的那道灼灼目光里。:冬天就是围巾，雪花，唇边的白雾，还有拽紧他的手不放的你。:来年的惊喜，会藏在拂起你发梢的第一抹春风里。"
    },
    pieces_male_main_panel_sentence_lx = {
      common_config_value = "刻意转过脸的笑，泄露他一抹内心的隐秘。:雨声滴答滴答，心情却突然因他放晴。:想听到他的真心话，要用真心来交换。"
    },
    pieces_male_main_panel_sentence_lzy = {
      common_config_value = "只有你能敲开他的心扉，正如只有玫瑰才能盛开如玫瑰。:他不想去广袤的天地，只想依偎在你身边看窗外漫天雪景。:咕咚咕咚，锅里煮满了他要与你一起品尝的人间滋味。"
    },
    pieces_male_main_panel_sentence_xm = {
      common_config_value = "跨越新年只要一瞬，而一瞬却因你被切分成许多微小的永恒。:如果清晨醒来发现你在，他会如同跌进一场轻柔的梦里。:电话里传来一阵嘈杂，他从中听见你呼喊他的姓名，淡淡笑了。"
    },
    pieces_male_main_panel_sentence_zql = {
      common_config_value = "要歌颂冬夜里烤红薯的香气，也要握紧掌心属于你的温暖。:默数三，二，一，在烟花升空前一起奔向你和他的又一年。:尝尝雪水包裹话梅糖的滋味，要和你一起孩子气地幼稚一回。"
    },
