  [39009] = {
    pieces_common_share_sentence = {
      common_config_value = "#MrLoveMobile  Hidden in the little trick, are the two close hearts."
    },
    pieces_drop_k1 = {common_config_value = "0"},
    pieces_drop_k2 = {common_config_value = "0"},
    pieces_drop_need_cards = {common_config_value = "0"},
    pieces_icon_id = {common_config_value = "119451"},
    pieces_mal_share_sentence_xm = {
      common_config_value = "The only lie he told today was that he didn't miss you very much.:He smilingly saw through your tricks and nodded in pretended surprise.:For him, the fun of April Fool's Day was watching you having fun."
    },
    pieces_male_main_panel_sentence_bq = {
      common_config_value = "He didn't understand the point of the holiday but found the answer the moment he saw you smile.:Lying to him had consequences which were to be with him for the whole day.:Your sneak attack broke his calm veneer and made his ears turn red."
    },
    pieces_male_main_panel_sentence_lx = {
      common_config_value = "Under the most dramatic prank hid the most visible sincerity.:Instead of going along with your tricks, he put a pair of bunny ears on you.:Whenever you got any idea, he would stop you by pinching your face."
    },
    pieces_male_main_panel_sentence_lzy = {
      common_config_value = "The grumbles were fake, but the smile was real.:You tried to trick him, only to quietly give up when you met his soft gaze.:The spiced pudding was his revenge to your mischief."
    },
    pieces_male_main_panel_sentence_xm = {
