  [39010] = {
    pieces_common_share_sentence = {
      common_config_value = "#MrLoveMobile No reason is needed to love you."
    },
    pieces_drop_k1 = {common_config_value = "0"},
    pieces_drop_k2 = {common_config_value = "0"},
    pieces_drop_need_cards = {common_config_value = "0"},
    pieces_icon_id = {common_config_value = "119500"},
    pieces_mal_share_sentence_xm = {
      common_config_value = "To him, you will always be the cutest \"\"kid\"\" in the world.:You are so cute that he felt even more pity for that kiss that could've been even closer.:The childhood memories that he never had are now tainted with the new colors you added with him."
    },
    pieces_male_main_panel_sentence_bq = {
      common_config_value = "He can create a carefree world for you even now.:He used to dream big as a kid, of the distant places and skies. Now, you become a part of his dreams.:A child's love can be unconditional, and so is his for you."
    },
    pieces_male_main_panel_sentence_lx = {
      common_config_value = "The interlocked hands will no longer let go. Children can have their ways, so adults can too.:He knows how to make people happy instantly. Get closer, and he will tell you.:He is more talented than you in pretending to be a kid and asking for wishes."
    },
    pieces_male_main_panel_sentence_lzy = {
      common_config_value = "The childhood bubbles float, reflecting the small figure next to the sandcastle, overlapping on the interlocked hands at this moment.:In return for being childish with you, he also has a selfish request for you.:He never told you that you are the reason why the corners of his mouth raise."
    },
    pieces_male_main_panel_sentence_xm = {
      common_config_value = "To him, you will always be the cutest \"\"kid\"\" in the world.:You are so cute that he felt even more pity for that kiss that could've been even closer.:The childhood memories that he never had are now tainted with the new colors you added with him."
    },
    pieces_male_main_panel_sentence_zql = {
      common_config_value = "Loving someone is as simple as giving the sweetest candy to you only.:Your heart is the amusement park he wants to go to and doesn't want to leave the most.:It's difficult to confess love firmly and sincerely like a child. It's you who gives him the courage."
