  [39011] = {
    pieces_common_share_sentence = {
      common_config_value = "#MrLoveMobile His love for you will stand the test of time and continue to grow."
    },
    pieces_drop_k1 = {common_config_value = "0"},
    pieces_drop_k2 = {common_config_value = "0"},
    pieces_drop_need_cards = {common_config_value = "0"},
    pieces_icon_id = {common_config_value = "119767"},
    pieces_mal_share_sentence_xm = {
      common_config_value = "He has always been honest with you. Except for that time when he told you he wanted a hug because it was chilly.:You are the poem that only belongs to him, giving him the unique and splendid insight that he desires, ingenious beyond description.:Ever since you stumbled into his eyes, all words that describe beauty have taken up a new form."
    },
    pieces_male_main_panel_sentence_bq = {
      common_config_value = "The evening breeze proceeded him. He stepped forth and wrapped his arms around you.:The gentle kiss on your hair delivers tranquility akin to the gentle breeze outside your window.:Tell him your wish boldly, and he will grant like the genie inside the lamp and even more quickly."
    },
    pieces_male_main_panel_sentence_lx = {
      common_config_value = "Among the bursting fireworks, he approached your ear, yet his loving whispers are as clear as the reflection in his eyes.:Although only children wish upon a star, seeing your devout expression, he still closed his eyes nevertheless.:He never did like a crowd. In a world with so many distractions, you will always be his sole fixation."
    },
    pieces_male_main_panel_sentence_lzy = {
      common_config_value = "Just like the finest cup of hot wine, he always shows his softest side with you beside him.:He doesn't need a cooking assistant, but whenever you're around, the temperature is always just right.:His true thoughts are hidden within every longing kiss and sincere word."
    },
