  [39012] = {
    pieces_common_share_sentence = {
      common_config_value = "#MrLoveMobile My heart never lies, not even on April Fool's Day."
    },
    pieces_drop_k1 = {common_config_value = "0"},
    pieces_drop_k2 = {common_config_value = "0"},
    pieces_drop_need_cards = {common_config_value = "0"},
    pieces_icon_id = {common_config_value = "119783"},
    pieces_mal_share_sentence_xm = {
      common_config_value = "He's found new joy in April Fool's day, to unravel the effort you've put into each prank.:He'll do all in his power to lean closer to your pursing mouth when you feign anger.:He draws closer to \"\"better observe your expression and verify whether what you say is true.\"\""
    },
    pieces_male_main_panel_sentence_bq = {
      common_config_value = "He refuses to speak a single untrue word to you, even if that means going against the law of April Fool's Day.:Having seen what you hide behind you in the reflection of the glass, he still smiles and keeps his eyes shut.:He found happiness and joy in joining the busy festival with you."
    },
    pieces_male_main_panel_sentence_lx = {
      common_config_value = "You avoided his prank toy and instead crashed right into his open arms.:You close your eyes and await punishment, yet soon feel a warm tingling breath upon your lips.:He feels confident that he will be your equal whether in terms of playing tricks or love."
    },
    pieces_male_main_panel_sentence_lzy = {
      common_config_value = "Tears welling up inside, you sift through the proposal that needs to be rewritten, only to find a note at the very end saying \"\"approved.\"\":Bearing all your pranks without complaint is a sign that you've got a place in his heart.:He accepts your elaborate pranks with open arms as he loves the notion of you spending time thinking of him."
    },
    pieces_male_main_panel_sentence_xm = {
      common_config_value = "He's found new joy in April Fool's day, to unravel the effort you've put into each prank.:He'll do all in his power to lean closer to your pursing mouth when you feign anger.:He draws closer to \"\"better observe your expression and verify whether what you say is true.\"\""
    },
    pieces_male_main_panel_sentence_zql = {
      common_config_value = "He comes bearing two secrets. The toy in his left hand leads to a prank, while the flowers in his right to a big surprise.:He carefully picks up his self-made cuteness detector and probes around. Moving toward you, he starts humming faster and faster.:When competing with you who can create the shortest poem that encapsulates this perfect day, all he writes is your name."
    },
    pieces_male_share_sentence_bq = {
      common_config_value = "He refuses to speak a single untrue word to you, even if that means going against the law of April Fool's Day.:Having seen what you hide behind you in the reflection of the glass, he still smiles and closes his eyes shut.:He found happiness and joy in joining the busy festival with you."
    },
    pieces_male_share_sentence_lx = {
      common_config_value = "You avoided his prank toy and instead crashed right into his open arms.:You close your eyes and await punishment, yet soon feel a warm tingling breath upon your lips.:He feels confident that he will be your equal whether in terms of playing tricks or love."
    },
    pieces_male_share_sentence_lzy = {
      common_config_value = "Tears welling up inside, you sift through the proposal that needs to be rewritten, only to find a note at the very end saying \"\"approved.\"\":Bearing all your pranks without complaint is a sign that you've got a place in his heart.:He accepts your elaborate pranks with open arms as he loves the notion of you spending time thinking of him."
    },
