  [39014] = {
    pieces_common_share_sentence = {
      common_config_value = "#恋与制作人#明月何皎皎，与君共此时。"
    },
    pieces_drop_k1 = {common_config_value = "0"},
    pieces_drop_k2 = {common_config_value = "0"},
    pieces_drop_need_cards = {common_config_value = "0"},
    pieces_icon_id = {common_config_value = "119897"},
    pieces_mal_share_sentence_xm = {
      common_config_value = "你用毛笔画了一幅月宫大作，他笑着在看不出形状的玉兔旁添了一只雪狐。:他用枫叶写下诗篇，装入一封秋凉，贴上月光邮票，交由你一吻封缄。:清晨发间的桂花瓣，是他昨夜在梦中为你捕来的月亮。"
    },
    pieces_male_main_panel_sentence_bq = {
      common_config_value = "秋夜蔓蔓，看天上月，吹人间风，伴意中人。:他让风推着月光，涂抹整片夜色，温柔地降落在你的身上。:枝头簌簌作响的桂叶，是他向你传达的即将归家的讯号。"
    },
    pieces_male_main_panel_sentence_lx = {
      common_config_value = "他漫不经心地接过被折坏的小熊猫，归还的时候还附赠了一只小兔子。:他在夜色中拉着你长奔，和秋夜同样清凉的体感温度中，握着的手格外滚烫。:吃过小饼后甜腻的口感，很快被带着碳酸气泡的清凉攻占。"
    },
    pieces_male_main_panel_sentence_lzy = {
      common_config_value = "他将微醺的你揽入怀中，轻笑着任凭你在他的衬衫上寻觅清凉。:缠绵的不只是灯火，还有斑驳月影里，你们渐渐靠近的轮廓。:你故意将月饼果酱抹在他的嘴角，却在他眼底看见一抹晕开的瑰色。"
    },
    pieces_male_main_panel_sentence_xm = {
      common_config_value = "你用毛笔画了一幅月宫大作，他笑着在看不出形状的玉兔旁添了一只雪狐。:他用枫叶写下诗篇，装入一封秋凉，贴上月光邮票，交由你一吻封缄。:清晨发间的桂花瓣，是他昨夜在梦中为你捕来的月亮。"
    },
    pieces_male_main_panel_sentence_zql = {
      common_config_value = "看着你一点点挤进他怀里的模样，他坏心地希望，今夜的气温可以再凉一些。:彼此依偎间，夜空的星星和你的眼睛都眨了一下，可他的心动，却不止一下。:他偷尝一口你的甜蜜，化作馅料，做一个可爱满分的甜月亮。"
    },
