  [39015] = {
    pieces_common_share_sentence = {
      common_config_value = "#恋与制作人#恋语绵绵，致你与他的又一年。"
    },
    pieces_drop_k1 = {common_config_value = "0"},
    pieces_drop_k2 = {common_config_value = "0"},
    pieces_drop_need_cards = {common_config_value = "0"},
    pieces_icon_id = {common_config_value = "400070"},
    pieces_mal_share_sentence_xm = {
      common_config_value = "每年新岁，他拥你入怀，在灯影摇曳间，共数胶片下私藏的过往。:你指向窗外，兴奋地表述着眼前雪景，他嘴角上扬，眼睛却始终没看过雪。:他落在枕边的呼吸仿佛海浪轻起，直教你溺落海底，被揉进新年的第一场梦里。"
    },
    pieces_male_main_panel_sentence_bq = {
      common_config_value = "想必是谁的温柔把月亮包裹起来了，才叫今夜的月色清烁，风也柔和。:冬时的阳光吝啬不肯露面，他牵起你的手，只说你的笑脸便是最好的天气。:岁寒时凝落的第一滴冬露，也不及他看向你时眼底的情意清澈。"
    },
    pieces_male_main_panel_sentence_lx = {
      common_config_value = "若今夜沉邃无星，他便为你燃上一场小小的烟火，照亮你的新年。:虽然嘴上说着大头照幼稚又无聊，可九张连拍，可是有八个动作出自他手。:他声称自己从来懒得看爱情故事，可你心仪的那些美好桥段，他都知道。"
    },
    pieces_male_main_panel_sentence_lzy = {
      common_config_value = "在拥挤吵闹的人群中他似乎总是沉默，只把千万句情话溶于悄悄握紧的方寸指尖。:新年清晨的枕下藏着惊喜的秘密，他永远不会让你的期待落空。:所谓新年对他不过是时间流转，可你在身边，他总觉得欣喜。"
    },
    pieces_male_main_panel_sentence_xm = {
      common_config_value = "每年新岁，他拥你入怀，在灯影摇曳间，共数胶片下私藏的过往。:你指向窗外，兴奋地表述着眼前雪景，他嘴角上扬，眼睛却始终没看过雪。:他落在枕边的呼吸仿佛海浪轻起，直教你溺落海底，被揉进新年的第一场梦里。"
    },
    pieces_male_main_panel_sentence_zql = {
      common_config_value = "向新年初升的第一颗星星许愿，岁岁年年，只做你平淡日子里的灿烂星辰。:他悄悄在院中埋下花种，等到冬雪融于春时，这些美好便为你盛开。:偷偷瞟向他的新年计划书，每一栏上都写着要再多喜欢你一点。"
    },
