  [39019] = {
    pieces_common_share_sentence = {
      common_config_value = "#恋与制作人#春景日日新，何不与君同。"
    },
    pieces_drop_k1 = {common_config_value = "0"},
    pieces_drop_k2 = {common_config_value = "0"},
    pieces_drop_need_cards = {common_config_value = "0"},
    pieces_icon_id = {common_config_value = "400444"},
    pieces_mal_share_sentence_xm = {
      common_config_value = "你在起雾的窗上悄悄留下他名字时，发现窗里也倒映着他眉眼弯弯的笑脸。:他饺子包得越来越娴熟，可还是会“不小心”蹭上面粉，来等你帮他擦掉。:你们吱呀吱呀地踩在雪地上，留下一个个亲昵又缠绵的脚印。"
    },
    pieces_male_main_panel_sentence_bq = {
      common_config_value = "你在祈福风铃上为他写了“新岁平安”，从此每一声铃响都落进他心底。:你说想看雪，他悄悄让风沿着窗缝把冬天送进家来，也没忘把你抱得更紧。:今晚月光熹微，但他并不在意，因为最美的月色一直在眼前。"
    },
    pieces_male_main_panel_sentence_lx = {
      common_config_value = "虽然早就看到你在悄悄靠近，但他翘了翘嘴角，还是散漫地装作被你吓到。:闪着电光的烟花应着钟声绽放，你们的新一年，从噼里啪啦的年味开始。:他睁开眼睛，侧头看向刚在梦中出现的你。眉峰微挑，笑着将你拥得更紧。"
    },
    pieces_male_main_panel_sentence_lzy = {
      common_config_value = "一桌美食配上鲜花和礼物，他将爱意准备万全，只愿你喜乐顺意。:零点收到了他厚厚的压岁包，你去年随口说的愿望，他却一直放在心上。:虽然他说为了守岁熬夜是“傻事”，却会每年都陪你一起。"
    },
    pieces_male_main_panel_sentence_xm = {
      common_config_value = "你在起雾的窗上悄悄留下他名字时，发现窗里也倒映着他眉眼弯弯的笑脸。:他饺子包得越来越娴熟，可还是会“不小心”蹭上面粉，来等你帮他擦掉。:你们吱呀吱呀地踩在雪地上，留下一个个亲昵又缠绵的脚印。"
    },
    pieces_male_main_panel_sentence_zql = {
      common_config_value = "晨光掠过他上扬的唇角，这一抹笑容，是与你一同看日出的幸福弧度。 :明明吃着热腾腾的火锅，他还是紧挨在你身边，贪恋着此刻上升的温度。 :醒来后你从枕头下摸到一个红包，里面是满满的糖果，也是他满满的甜。"
    },
    pieces_male_share_sentence_bq = {
      common_config_value = "你在祈福风铃上为他写了“新岁平安”，从此每一声铃响都落进他心底。:你说想看雪，他悄悄让风沿着窗缝把冬天送进家来，也没忘把你抱得更紧。:今晚月光熹微，但他并不在意，因为最美的月色一直在眼前。"
