  [39022] = {
    pieces_common_share_sentence = {
      common_config_value = "#恋与制作人#同君携手度，日月朝暮中。"
    },
    pieces_drop_k1 = {common_config_value = "0"},
    pieces_drop_k2 = {common_config_value = "0"},
    pieces_drop_need_cards = {common_config_value = "0"},
    pieces_icon_id = {common_config_value = "400744"},
    pieces_male_main_panel_sentence_bq = {
      common_config_value = "凑近的唇间弥漫着他的轻语，于风中倾诉着心绪。:面的热气腾腾，摩托的风驰电掣，他的爱是与你的日常点滴。:问题再难也不会令他迷失方向，只要风中有你，便有了路。"
    },
    pieces_male_main_panel_sentence_lx = {
      common_config_value = "一起滑滑板时他说要保持平常心，可你知道他的心在越跳越快。:历史只要发生就总会留下痕迹，他的生活也早已擦不掉你。:他总是故作寻常地拿出一份份礼物，里面却全是精心准备的惊喜。"
    },
    pieces_male_main_panel_sentence_lzy = {
      common_config_value = "冬日的大衣下拥簇着温度，包裹了他对你无法遏制的爱意。:他的烹调手法千变万化，始终是你最爱的那一味。:他向来把自己的一切安排得井井有条，却总为你放下了时间概念。"
    },
    pieces_male_main_panel_sentence_xm = {
      common_config_value = "他口中的每次碰巧撞见，都是命运安排的注定相遇。:能令他烦恼的课题很多，可他明白，真理和你都是独一无二的存在。:对他来说，顾问要解开的不只是问题，还有你皱起的眉头，烦闷的心。"
    },
    pieces_male_main_panel_sentence_zql = {
      common_config_value = "软软的棉花糖，浓浓的巧克力，是他想带给你的甜蜜。:在冬日阳光中感受彼此的呼吸，是你们才懂的小确幸。:天空中闪耀的不止星星，还有很多他为你许下的愿望。"
    },
    pieces_male_share_sentence_bq = {
      common_config_value = "凑近的唇间弥漫着他的轻语，于风中倾诉着心绪。:面的热气腾腾，摩托的风驰电掣，他的爱是与你的日常点滴。:问题再难也不会令他迷失方向，只要风中有你，便有了路。"
    },
