  [42002] = {
    daily_reward_id = {common_config_value = "0,2"},
    daily_reward_range = {common_config_value = "50:88"},
    double_activity_male_special_talk_1 = {
      common_config_value = "Take it if you like it, it's yours.:A small gift.\\nIf it makes you happy, then it was worth it.:Ding-dong! You have received a gift, check it out!:I've got a present for you.:Why the weird expression? Me giving you a gift isn't that unusual."
    },
    double_activity_male_special_talk_2 = {
      common_config_value = "Since it's from you, I'll accept it.:Can I open it now?\\nI'm curious what you prepared this time.:A return gift from Miss Chips, I'll treasure it.:...You have something for me?:It took you a long time to get it? Do you need me to appraise it?"
    },
    double_activity_male_special_talk_3 = {
      common_config_value = "This is the surprise you talked about? It's very much like you.:Thanks, I like it a lot.\\nBut now I need to consider a return gift in earnest.:How did you find such a great gift!:I didn't thought I would get this...I like it very much.:This is not bad! I like it."
    },
    double_activity_male_talk_1 = {
      common_config_value = "No reason, just thought somebody would appreciate it.:The gift is but a gesture, but hope you like it.:Ta-da! Kiro's exclusive surprise! Do you like it?:I thought you'll like it, so I bought it... How is it?: Take this. Don't ask me why. I'm giving it to you so keep it."
    },
    double_activity_male_talk_2 = {
      common_config_value = "Return gift? If you are giving me one then do it.:You mentioned return gift? Can I ask for a hug?: You prepared a gift for me too? We are so in sync!:Huh?Is this... a gift for me?:Return gift? I'm curious what you have came up with."
    },
    double_activity_male_talk_3 = {
      common_config_value = "Your taste has improved, not bad this time.:The gift is very special, I'll treasure it.:I have thought of getting this for a long time! Thank you so much!:I will keep it safe, thank you.:Since you put efforts into it, I'll accept the gift."
    },
    double_activity_my_gift = {
