  [42003] = {
    daily_reward_id = {common_config_value = "0,2"},
    daily_reward_range = {common_config_value = "50:88"},
    double_activity_male_special_talk_1 = {
      common_config_value = "This is my future expectation for a certain dummy, take it.:Just a small gift.\\nSince it had made you happy like this, the gift is totally worthy.:I have hidden a bunch of happiness in the gift, have Miss Chips seen it?:Happy Valentine's Day. I brought you a gift.:Well, for the future, I wish you lucky, happy,\\nand good fortune..."
    },
    double_activity_male_special_talk_2 = {
      common_config_value = "A \"\"surprise\"\" for me?: Really? you have a gift for me?:Let me guess what will your gift be...:Is it for me?:Stop hiding it. I've seen the gift behind you."
    },
    double_activity_male_special_talk_3 = {
      common_config_value = "Your intention is just so likeable.:Since I have received your blessings, I'll have to think seriously about what my gift for you will be.:It is 100% for sure my favourite gift this year!: I kind of understand the interest of giving gifts to each other.:Did you ever studied my likes? You've got it right."
    },
    double_activity_male_talk_1 = {
