      common_config_value = "Return gift? If you are giving me one then do it.:You mentioned return gift? Can I ask for a hug?: You prepared a gift for me too? We are so in sync!:Huh?Is this... a gift for me?:Return gift? I'm curious what you have came up with."
    },
    double_activity_male_talk_3 = {
      common_config_value = "Your taste has improved, not bad this time.:The gift is very special, I'll treasure it.:I have thought of getting this for a long time! Thank you so much!:I will keep it safe, thank you.:Since you put efforts into it, I'll accept the gift."
