  [42004] = {
    daily_reward_id = {common_config_value = "0,2"},
    daily_reward_range = {common_config_value = "50:88"},
    double_activity_male_special_talk_1 = {
      common_config_value = "Here is the New Year gift I promised someone. Be on time to redeem it.:My New Year blessings for a certain little friend are hidden in this gift.:Beep-beep! Your New Year Grand Gift Pack has arrived.\\nRedemption Code - Happy New Year!:I hope this year's New Year gift hasn't arrived late.:Come get your New Year gift. I didn't forget."
    },
    double_activity_male_special_talk_2 = {
      common_config_value = "Which gift of yours have I ever not cherished?\\nI'm always ready for a 'surprise'.:I have a gift too?\\nLet me guess what $u thought to give me...:Wow! I'm already excited just seeing the gift!:For me? Yeah, of course I'm happy. Really looking forward to it.:What's for me? The one with lots of bells and whistles?"
    },
    double_activity_male_special_talk_3 = {
      common_config_value = "Remember to come to Souvenir tonight.\\nThere's a limited edition New Year's feast someone's been yammering on about.:In terms of picking gifts, my little girl is quite the talent.:Miss Chips, you're top-tier at picking gifts!\\nI almost can't bear to tear it open!:I gladly accept the gift, and the gift-giver.:You've got a knack for picking gifts.\\nHow do you know me so well?"
    },
    double_activity_male_talk_1 = {
      common_config_value = "The thing on someone's 'wish list', I just happened to see it and bought it.:I imagined what you'd look like holding it, so I decided to give it to you.:Gift from [Kiro] to [Miss Chips] has been delivered.\\nEstimated Intimacy Pt. boost - 100 pts.:I think this suits you. Do you like it?:I knew you'd like it. Hang on to it then."
    },
    double_activity_male_talk_2 = {
      common_config_value = "A gift that really suits me? We'll see about that.:Actually... the look in your eyes has already given away that you are 'hiding a gift'.:[Miss Chips] is giving you a thank-you gift!:...You bought a little gift that suits me too?:Woah, you mean that package I just received is a thank-you gift?"
    },
    double_activity_male_talk_3 = {
      common_config_value = "I've got another item for my 'Dummy Style' collection.:The little gifts you give always add a special beauty to my life.:[Kiro]'s Intimacy Pt. with [Miss Chips] is off the charts!:I really like it, whether it's the gift, the thought behind it, or the person giving it.:You must have put a lot of time into this gift, eh? Thanks!"
    },
    double_activity_my_gift = {
      common_config_value = "Window decoration:Calendar:Lantern:Gift card:Caligraphy:Painting:Scarf:Snacks:Fruit basket:Firework"
    },
    double_activity_special_talk_time = {
      common_config_value = "2023/1/19 5:00;2023/1/26 23:59"
    },
    first_day_deadline = {
      common_config_value = "2023/1/21 4:59:59"
    },
    pay_info_id = {common_config_value = "420041"},
    pay_info_ids = {
      common_config_value = "420041:420042"
    },
    return_present_item = {common_config_value = "119766"},
    reward_double_price = {common_config_value = "1"}
  },
  [42005] = {
    daily_reward_id = {common_config_value = "0,2"},
    daily_reward_range = {common_config_value = "50:88"},
    double_activity_male_special_talk_1 = {
      common_config_value = "Quit staring at me like that. I have your New Year gift right here.:I've prepared your New Year gift a long time ago. Of course my little bunny's going to get a gift from me.:I got you a gift that I'm sure you'll love to death, Miss Chips!:I began preparing a long time ago just so I could be the first one to give you your New Year gift.:When it comes to our gift's surprise factor, I doubt you'll be able to beat me this year."
    },
    double_activity_male_special_talk_2 = {
      common_config_value = "Let me guess what I'm going to get in return. No matter what I guess, you have to give it to me.:I look forward to finding out what you've prepared for me this year.:Hehe. I've been looking forward to this. I knew you were going to get me a New Year gift this year too.:What I want the most for the New Year? Hm... I want us to be happy and together the whole year.:Ha! I'd like to see you try and top my gift this year."
    },
    double_activity_male_special_talk_3 = {
      common_config_value = "This year's gift was quite creative. You certainly have a knack for strange ideas.:That gift is awesome. You always have a way to come up with interesting surprises.:Whoa! Did you check my shopping list or something? I just put this in yesterday!:Let's exchange gifts every year from now on!:Fine. I'll reluctantly call us evenly matched this year."
    },
    double_activity_male_talk_1 = {
      common_config_value = "It looked like something a certain someone would like, so I just bought it without thinking.:I got you a little something. Try to guess what's in the box?:This is a special surprise gift I prepared for Miss Chips. You'll definitely like it!:I saw you looking at it for a long time while shopping the other day, so I bought it for you. Do you like it?:Take it. It's a trinket I bought on the roadside, I knew at first glance you would like it."
    },
    double_activity_male_talk_2 = {
      common_config_value = "You want to give me a gift too? Is it going to be some silly little trinkets again?:The gifts you give me are always the most special.:Wow! Did you also prepare a gift for me? Can I open it now?:You also got me a gift? You didn't have to prepare anything. You always give me the best gifts anyway.:Huh, feeling embarrassed to take it for free? Getting all shy with me now?"
    },
    double_activity_male_talk_3 = {
      common_config_value = "This is a gift that only you would think to give. I'll treasure it.:The gifts you choose are always so interesting, I should think carefully about what surprise to prepare for you next time.:How did you know I wanted this?! Thank you! I've been wanting this for so long!:Great gift! Let me give you another one to make it a pair.:Well, well, well. I see you put in some effort. A very interesting gift indeed."
    },
    double_activity_my_gift = {
      common_config_value = "Window Paper-cut:Calendar:Lantern:Red Packet:New Year Scroll:Good Fortune:Scarf:Snacks:Fruit Plate:Firecrackers"
    },
    double_activity_special_talk_time = {
      common_config_value = "2024/1/1 5:00;2024/1/2 23:59"
    },
    first_day_deadline = {
      common_config_value = "2023/12/23 4:59:59"
    },
    pack_current_price = {common_config_value = "1.99"},
    pack_original_price = {common_config_value = "2.99"},
    pay_info_id = {common_config_value = "420043"},
    pay_info_ids = {
      common_config_value = "420043:420044"
    },
    return_present_item = {common_config_value = "400069"},
    reward_double_price = {common_config_value = "0.99"}
  },
  [42006] = {
    daily_reward_id = {common_config_value = "0,2"},
    daily_reward_range = {common_config_value = "50:88"},
    double_activity_male_special_talk_1 = {
      common_config_value = "You said you were missing a little Valentine's Day spirit at home—this should do the trick.:Not sure if this counts as a decent first Valentine's gift, but I hope it will.:Come on, Miss Chips. Can you guess what I've prepared for you this Valentine's Day?:Happy Valentine's Day! This gift is all yours—and of course, all my time's yours, too.:Happy Valentine's Day! Here's a little something for you. Am I good to you or what?"
    },
    double_activity_male_special_talk_2 = {
      common_config_value = "Of course I want to get a gift from you—I've always known how thoughtful you are.:If I guess what your gift is, do I get a bonus present?:There's really no one else like you when it comes to picking gifts, Miss Chips. Let me see what you got!:I already saw you hiding something behind your back.:I know you brought me a gift—no need to hide it. Let's see it."
    },
    double_activity_male_special_talk_3 = {
      common_config_value = "You really come up with fresh ideas every year. A single pudding just might not cut it this year.:With this gift in hand, I've got a feeling the new year will be even better than I imagined.:You've got a real knack for picking gifts—you always hit my favorites right on the mark!:I love every gift you've ever given me; they're all from you, after all.:People say relationships will sail smoothly if we have something nice for this special day, and your gift alone does the job for me."
    },
    double_activity_male_talk_1 = {
      common_config_value = "You don't need a special occasion to give a gift. If something fits just right, I'll naturally think of giving it to you.:Could I trade this little present for your smile?:Ta-da! The awesome Kiro is back with a little gift for you!:My gift-picking skill is ready for your inspection, Miss.:It might not look like much, but I spent days hunting for this."
    },
    double_activity_male_talk_2 = {
      common_config_value = "A return gift for me? Sounds like something I can look forward to.:An extra gift from you? Looks like I can be a bit greedier and expect a return gift from you.:I can't wait to see the surprise you've prepared.:You thought of me when you saw it? Guess our gift standards are totally in sync.:You've got something for me, huh? I don't even need to guess—your face says it all."
    },
    double_activity_male_talk_3 = {
      common_config_value = "At this rate, one room might not be enough to store all the gifts you've given me.:Now I really need to figure out what I'm gonna get you next time.:Uh oh, now I feel like your return gift deserves an even better present from me.:Hmm... What should I pick as a return gift for this return gift?:You've really gone out of your way to pick these flashy things. Don't worry, I'll keep them all safe."
    },
    double_activity_my_gift = {
      common_config_value = "Chocolate:Plushie:Flowers:Love Balloon:Cake:Snacks:Scarf:Mittens:Wool Hat:Valentine's Day Card"
    },
    double_activity_special_talk_time = {
      common_config_value = "2025/2/14 5:00;2025/2/14 23:59"
    },
    first_day_deadline = {
      common_config_value = "2025/2/9 23:59:59"
    },
    pack_current_price = {common_config_value = "12"},
    pack_original_price = {common_config_value = "18"},
    pay_info_id = {common_config_value = "420045"},
    pay_info_ids = {
      common_config_value = "420045:420046"
    },
    return_present_item = {common_config_value = "400443"},
    reward_double_price = {common_config_value = "1"}
  },
  [42007] = {
    daily_reward_id = {common_config_value = "0,2"},
    daily_reward_range = {common_config_value = "50:88"},
    double_activity_male_special_talk_1 = {
      common_config_value = "希望这件礼物，能满足某人关于新年的期盼。:希望这份礼物，可以让你的脸上绽放新年的第一份笑容。:今年的第一份惊喜已就位，只等我的家薯来亲手揭晓了！ :新年快乐，祝福和礼物我都想第一个送给你。:既然收了礼物，是不是该送我句特别的新年祝福？"
    },
    double_activity_male_special_talk_2 = {
      common_config_value = "对于笨蛋准备的礼物，我一向有所期待。:你总能从生活的点滴中发现我的一切，哪怕只是一份小小的喜好。:时间可以快一点，再快一点吗？迫不及待想知道阿薯准备的惊喜啦~:我的新年礼物，好像已经被你藏在手中了。:你送的我肯定喜欢？算你猜对了吧。"
    },
    double_activity_male_special_talk_3 = {
      common_config_value = "介于你这次的奇思妙想还不错，我的新年回礼自然也要深思熟虑。:关于新一年的第一份想象与期许，是你亲手送给我的。:原来魔法师就在我身边~你的每一份惊喜都有让人感到幸福的魔力。:送你的新年回礼当然要仔细挑选，我的女孩值得最好的。:新年当然要接福气、迎好运，你亲手送的礼物，我可得收好才行。"
    },
    double_activity_male_talk_1 = {
      common_config_value = "我记得某人说过，生活需要仪式感。:这份小礼物，希望能和我一起陪伴你今天的好心情。:当当~周棋洛专属礼物送达~请签收！:在你身边，我也学到了不少挑礼物的方法。:这礼物还行吧？我可是耐着性子挑了半天。"
    },
    double_activity_male_talk_2 = {
      common_config_value = "笨蛋认真准备的心，比礼物更值得惊喜。:是你让我渐渐知道，未知与等待也伴随着幸福的模样。:好想知道你准备了什么惊喜，可以给我透露一点吗？:不用太费脑筋，你选的我都喜欢。:跟我就别卖关子了，你带了什么我还猜不出来？"
    },
    double_activity_male_talk_3 = {
      common_config_value = "看来又见识到了一次，某人层出不穷的创意。:这位小姐的礼物，总能让我发自内心地感到快乐。:嗯……让我来想想，怎么给你独一无二的回礼~:其实礼物是什么不重要，是你送的就足够好。:有些人真是跟我待久了……你别说，这些东西有点意思。"
    },
    double_activity_my_gift = {
      common_config_value = "窗花:年历:灯笼:红包:春联:福字:围巾:零食:果盘:鞭炮"
    },
    double_activity_special_talk_time = {
