    },
    mayday_travel_game_2_reward = {
      common_config_value = "119113,101,6"
    },
    mayday_travel_games_desc = {
      common_config_value = "The view here is amazing. Let's take some pictures. : The view here is amazing. Let's take some pictures."
    },
    mayday_travel_games_probability = {
      common_config_value = "1|4000:2|6000"
    },
    mayday_travel_lx_common_words = {
      common_config_value = "You don't need to prepare anything. Just follow me."
    },
    mayday_travel_lx_special_words = {
      common_config_value = "Since you are so interested, I will recommend several books to you: A \"\"mild spicy\"\" hot pot is not a true hotpot, but I'll accommodate you this time. : Since I won it for you, I'll keep it for you. When you want to go, you must go with me. : What? I've told you that I'm a top student. : It's just hiking, and you're so tired already?"
    },
    mayday_travel_notes_day_1 = {
      common_config_value = "The museum holds special exhibitions regularly, and we are visiting the museum for the next painting and calligraphy exhibition. : Shaw brought me to the Loveland Museum and we visited a special lacquerware exhibition. He shared with his knowledge on lacquerware, and I actually benefited a lot from it."
    },
    mayday_travel_notes_day_2 = {
      common_config_value = "A new hotpot restaurant just opened downtown. I heard that the food there was extremely spicy, and Shaw insisted on trying it out with me! : Although I made up my mind to challenge \"\"hellish spicy\"\" before we got there, I gave up when I smelled the chili oil, and so did Shaw."
    },
    mayday_travel_notes_day_3 = {
      common_config_value = "Shaw and I participated in a special event held by a fried chicken restaurant, and we won a one-year fired chicken discount card! : When Shaw and I passed by the Fried Chicken Restaurant, we found them holding a \"\"Whac-A-Mole\"\" special event, participated and won the super prize. Although he refused to admit that he wanted the discount card all to himself, I took no notice of it as we really had a great time."
    },
    mayday_travel_notes_day_4 = {
      common_config_value = "You came to the studio at 7 a.m. just to bring me to the library? : Sorry... Teachers! It was Shaw who threatened me with my life, forcing me to act as his lookout. We didn't steal anything though. We just climbed in from the window and read some papers that we were not allowed to borrow..."
    },
    mayday_travel_notes_day_5 = {
      common_config_value = "After hiking, I collapsed. : Shaw could run to the top of the mountain without a break? Young people were really energetic..."
    },
    mayday_travel_notes_unlock_cnt = {common_config_value = "5"},
