  [66002] = {
    last_guide_banner = {
      common_config_value = "86012:86011:86010:86009:86008:86007:86006:86005:86004:86003:58006:255:206:61001:10001:106:107:9042:111:145"
    },
    role_feedback_random_1 = {
      common_config_value = "Why are you meandering about, are you hungry?; Lean on me if you're sleepy, don't fidget.;The cake you've been longing for has been delivered, come and eat.;What's wrong, is there something you want to tell me?;Give me your hand. Don't you want me to hold it?;I have been busy these few days, but I promise to compensate you in the future.;Come sit beside me if you want to watch this movie.;Just stay here from now on.;No matter what, don't leave me again.; ... Nothing. Just checking to see if you're here.;I don't have to finish what I want to do today. Right now, my time is all yours.; Come have a cup of coffee with me."
    },
    role_feedback_random_2 = {
      common_config_value = "I saw a kitten that looks like you on the road.; How about you stay with me for a little while, and I will accompany you for the rest of the night.;Let's go for a walk hand in hand.; Can I make a small request if I cooperate with you?; You are as beautiful as usual today.;This seems to be a long movie, are you ready to spend the whole night with me?;Come look for me directly at the laboratory if you have urgent matters.;The advantage of observation lies in the objective perspective, but I can't manage that when observing you.;Everything seems lovely when you're by my side.;You can slowly tell me what you want to say and I'll listen carefully.;You look really pretty when you smile.;Garda on the windowsill missed you. I missed you too."
    },
    role_feedback_random_3 = {
      common_config_value = "It seems that my wish has come true, you really showed up!; I have a little bunny in my heart. She is the kindest and most lovely bunny that belongs only to me.;Seeing you always makes me happy. It must be some kind of magic spell.;I saw the kittens having a meeting and decided to eavesdrop.;The sunshine is very warm today, just like Miss Chips.;Any song that you want to listen to?;Don't move, let me hold your hand for a little while.;See those strangely shaped clouds in the sky? Don't they look like little monsters?;It's Kiro, the superhero show time!;Stay still, you've been seized, please hand over the strawberry cake!;Shall we bring Apple Case out to play?;I'll reserve the first row for you if you want to come to my concert next time."
    },
    role_feedback_random_4 = {
      common_config_value = "Do you want to go for a walk?; Just staying with you like this is also enjoyable.;Take a break if you have nothing to do. I will join you.;Well, I don't want to keep you waiting for long.;Eli invites us to a dinner together at night, are you free?;I'm here. Just let me know if there's anything.;What's wrong? Is there anything I can help WITH?;You're the only one I care about, other people's opinions don't concern me.;There are no rules that cannot be broken. You can of course just follow your own ideals.;I passed by some beautiful scenery a few days ago, but unfortunately you weren't there.;Would you like some steamed snow pear with rock sugar? You have been staring at the stall for a while now.;You're always the most beautiful person in my eyes."
    },
    role_feedback_random_5 = {
      common_config_value = "  Why so many questions? Just follow me.; You can use one of the earbuds, but I'll be in charge of the songs.;When you're wearing the Buddha beads, your hands look even smaller.;What's the matter? Missing me again?;The way you look at me is pretty cute.;Why did you come without telling me first? But I don't mind accompanying you for a while.; Just say it if you need me to accompany you. I can't read your hints.;Just do whatever you like. Why care so much about what others think?;Can you hum that song from last night again?; The band members are wondering what you've been busy with lately. It's been a while since you came to our performance.;Don't you get tired of staring at me every day?"
    },
    role_feedback_task_complete_1 = {
      common_config_value = "... Dummy. It's good that you're home.;No matter where you will go in the future, you must let me know.;Don't disappear for so long since you know you're always making people worried about you.;Since you're here, stay with me for a while.;You're someone I approve of, so be more confident.;I will fulfill my promise to bring you on vacation soon.;There's nothing important today, come rest with me for a while."
    },
    role_feedback_task_complete_2 = {
      common_config_value = "There's no need to explain. I'll be happy as long as you come back.;I could only confirm that it wasn't 'my illusion when you appear before me.;I know. You won't leave me again, right?;Since you're here, stay with me for a while.;I have a lot of time for you today, so you can take your time to plan.;I hope you could say good morning and good night to me every day."
    },
    role_feedback_task_complete_3 = {
      common_config_value = "You're finally back! Don't make me so worried again, okay?;I brought you a super delicious puff, come and try it!;I don't want to play hide-and-seek with you anymore.;Give me your hand. I want to check again that you're with me.;Do I seem clingy today? Well then, I am officially being clingy now.;Miss Chips looks like she's cream flavor today.;A good day begins with seeing you!"
    },
    role_feedback_task_complete_4 = {
      common_config_value = "I've been missing you the whole time you weren't here.;I don't want to... lose touch with you again.;I can accompany you to anywhere you want to go again.;Well... the wind tells me that you are still here.;If you don't have other plans today, let's go to see the places we used to visit.;I passed by some beautiful scenery a few days ago, but unfortunately you weren't there.;If you have no special plans for today, let's go for a ride together?"
    },
    role_feedback_task_complete_5 = {
      common_config_value = "So you still know where home is huh? I'd be really mad if you disappear for no reason again.;You left without saying a word. Are you upset about something?;Listen to me, I don't like waiting...;Don't try running away before I release my grip.;I like having you around 24 hours a day. What's wrong with that?;I haven't had much of an appetite lately. Let's have hot pot tonight.;Don't forget to watch my performance at Live House tonight."
    },
    shop_redpoint = {common_config_value = "119152,100"}
  },
