  [69001] = {
    BGM_vol = {common_config_value = "0.5"},
    activity_BGM = {
      common_config_value = "101_LiZeyan:201_XuMo:304_ZQL_SingforYou:404_Hazy_Starry_Night"
    },
    relate_activity = {
      common_config_value = "17023:17024:17025:17026"
    }
  },
  [69002] = {
    BGM_vol = {common_config_value = "0.15"},
    Intimatelevel_target = {
      common_config_value = "0:30:60:120"
    },
    Intimatelevel_text_1 = {
      common_config_value = "每多走近他一点，\\n就更懂众人夸赞的表象只是他最不起眼的那点。|冰山只露一角，在你面前，\\n却总在不经意就柔软成清澈透底的暖池。|那个看似遥不可及的人，\\n其实早就走到你身边，给出了全部信任。"
    },
    Intimatelevel_text_2 = {
      common_config_value = "他的笑容下，不论温柔还是陷阱，\\n你都义无反顾，选择一探究竟。|时间教会你如何驯服他，\\n教会他如何信任。|他有太多秘密，但没关系。\\n来日方长，他愿意一点点讲给你听。"
    },
    Intimatelevel_text_3 = {
      common_config_value = "分享了每个秘密，共享每个基地。\\n他是只属于你的周棋洛。|他是光，也是影。\\n光有光的闪耀，影有影的坚守。|一个眼神的暗示，一个举动的默契，\\n你们已经找到了最懂自己的人。"
    },
    Intimatelevel_text_4 = {
      common_config_value = "他不再是回忆中单薄的印象，\\n每一次了解，都让你更喜欢他一点。|他是阵奔涌入你生活的风，\\n把每个不同的侧面，都摊开在你面前。|最了解他的人是你，\\n最让他挂心的，也是你。"
    },
    Intimatelevel_text_8 = {
      common_config_value = "你们在试探着了解彼此这件事上，\\n都乐此不疲。|你看懂了他字里行间的心思，\\n也懂了他藏在心底的在意。|他还有很多有趣的事，\\n等你一起尝试。"
    },
    activity_BGM = {
      common_config_value = "65_2020anniversary_pv:65_2020anniversary_pv:65_2020anniversary_pv:65_2020anniversary_pv:65_2020anniversary_pv"
    },
    date_text_1 = {
      common_config_value = "你是他的惊喜，是他的誓言，是他对世界的回音。"
    },
    date_text_2 = {
      common_config_value = "他的心是一道幽谷，你终于看清了雾后的风景。"
    },
    date_text_3 = {
      common_config_value = "他始终能陪你一起发掘生活中的惊喜。"
    },
    date_text_4 = {
      common_config_value = "不需要夏天的蝉，轻风扬起，他就能去见你。"
    },
    date_text_8 = {
      common_config_value = "他逐渐把你纳进“个人所有”的范围圈里。"
    },
    phonetext_1 = {
      common_config_value = "他的每一次温柔你都想要炫耀，\\n也想偷偷当做独一无二的宝物。"
    },
    phonetext_2 = {
      common_config_value = "穿越海海人群，\\n只有你与他跳动着相同的频率，成为彼此的星球。"
    },
    phonetext_3 = {
      common_config_value = "他把两个字藏在了送给你的每句话里，\\n或许，如今那已不再是个秘密。"
    },
    phonetext_4 = {
      common_config_value = "像是生活里的每一次呼吸，\\n你填充着他的分分秒秒。"
    },
    phonetext_8 = {
      common_config_value = "你是闯入他生命中的惊雷，\\n他也乐得在你的世界刻下名为他的痕迹。"
    },
    relate_activity = {
      common_config_value = "17038:17039:17040:17041:17042"
    }
  },
  [69003] = {
    BGM_vol = {common_config_value = "0.1"},
    activity_BGM = {
      common_config_value = "106_LZY_Second:205_XuMo_Second:305_ZQL_Second:405_BaiQi_Second:801_LX_Second"
    },
    daily_img = {
      common_config_value = "1:1:1|2:2:2|3:3:3|4:5:6|7:8:9"
    },
    daily_target = {
      common_config_value = "0:40:80:140:200"
    },
    daily_text1 = {
      common_config_value = "       没时间养花就养好自己，观察笨蛋的成长过程也很有趣。|       现在已经能看出它日后蓬勃生长的气势了。|       现在已经能看出它日后蓬勃生长的气势了。|       因为某人天天在我耳边念叨，现在我也好奇，它会开出什么花了。|       可以给满分了，花和某个笨蛋的笑脸一样灿烂。"
    },
    daily_text2 = {
      common_config_value = "       我们可以一起学习一下如何养花，然后，一起实验。|       没关系，它很坚强，总会慢慢长大。|       没关系，它很坚强，总会慢慢长大。|       开花之前的日子总是过得很慢，因为它正在努力寻找自己最美的样子。|       我们见证了它的成长，它也见证了我们的陪伴。"
    },
    daily_text3 = {
      common_config_value = "       有薯片小姐和周棋洛的合作，一定能养出最健康的花。|       发芽就是成功的一半，现在，我们可以一起帮它完成另一半了。|       发芽就是成功的一半，现在，我们可以一起帮它完成另一半了。|       听说越晚开花，花朵越好看，让我们一起等最美的花盛开吧。|       这可是我们一起养的，开出来的花当然是全世界最好看的。"
    },
    daily_text4 = {
      common_config_value = "       等你有时间，我们一起养，小刺也想要个新伙伴了。|       长得慢，或许是因为它在厚积薄发。|       长得慢，或许是因为它在厚积薄发。|       修枝是个技术活，希望它别嫌我剪得不好。|       一起把它种下去那刻起，我就知道它一定会开花。"
    },
    daily_text8 = {
      common_config_value = "       窗台上还有一个可以放盆栽的位置，你看着办。|       长势不错，果然谁养的像谁。|       长势不错，果然谁养的像谁。|       下次可以多养几棵，毕竟等开花的日子也有点无聊。|       本来以为和你一起养东西是体验过程，没想到还能享受结果。"
    },
    date_text1 = {
      common_config_value = "       除了好吃的和出去玩，你尽可以提出更多的要求。"
    },
    date_text2 = {
      common_config_value = "       以后，多给我一些给你创造惊喜的机会吧。"
    },
    date_text3 = {
      common_config_value = "       握住你的手，就是我获取糖分的最佳方式。"
    },
    date_text4 = {
      common_config_value = "       最大的愿望，就是在每一次起风的时刻看到你。"
    },
    date_text8 = {
      common_config_value = "       想那么多以后的事干嘛，未来的事交给未来，我保证会有趣。"
    },
    final_text1 = {
      common_config_value = "       不用遗憾，错过的东西，以后会陪你一件一件补回来。|       你负责制定计划，我负责监督笨蛋开心地完成计划。"
    },
    final_text2 = {
      common_config_value = "       把这些事情留给未来的我们，他们一定会完成得很精彩。|       烟花短暂，信笺长留。一切的平凡，都因染上你的色彩变得更加明亮。"
    },
    final_text3 = {
      common_config_value = "       今年我们一起做的事情太多，把没做的事排到之后的档期吧。|       我还可以再和你一起看一百次烟花，写一百封信。"
    },
    final_text4 = {
      common_config_value = "       想说的话，我可以直接说给你听，想看的风景，现在可以一起去看。|       每一件事情都会想到你，这就是我的答案。"
    },
    final_text8 = {
      common_config_value = "       不是天天嚷嚷着想做各种事情吗？安排起来，这次我不迟到。|       没有嫌弃，我觉得挺有意思的，下次可以继续。"
    },
    hundred_accompany_flower_actid = {common_config_value = "8003"},
    hundred_accompany_score_actid = {common_config_value = "21624"},
    pet_text1 = {
      common_config_value = "       什么时候想养了就养，我习惯照顾笨蛋了，再加一只小的也没差别。|       我不在的时候，有“人”陪你胡闹了。"
    },
    pet_text2 = {
      common_config_value = "       在小动物分散你的精力前，我还可以独自霸占你的时间。|       “一家三口”的时间，是在忙碌工作中的最好期待。"
    },
    pet_text3 = {
      common_config_value = "       有机会的话，我还是想和薯片小姐一起养一只小动物。|       算上苹果箱和Cello，我们也算是其乐融融的大家庭了呢！"
    },
    pet_text4 = {
      common_config_value = "       想养什么我陪你，有你的双人任务我的效率更高。|       是时候给小黑再加一个小车座了，兜风的时候可以把你们都带上。"
    },
    pet_text8 = {
      common_config_value = "       听说养动物很麻烦，但和你一起的话，倒也不错。|       你们都是我罩着的，别被人欺负了。"
    },
    phone_text1 = {
      common_config_value = "       某个笨蛋总会以不同的方式陪在我身边。"
    },
    phone_text2 = {
      common_config_value = "       原来我们生活的节奏，已经逐渐不分彼此了。"
    },
    phone_text3 = {
      common_config_value = "       手机内存太小了，存不下我对你的所有心意。"
    },
    phone_text4 = {
      common_config_value = "       我想要生活中的每一件小事，都有你的身影。"
    },
    phone_text8 = {
      common_config_value = "       你是我手机里，唯一不受勿扰模式限制的人。"
    },
    read_rewards = {
      common_config_value = "119665,101,1|119667,101,1|119669,101,1|119671,101,1|119673,101,1"
    },
    relate_activity = {
      common_config_value = "17063:17064:17065:17066:17067"
    },
    start_text1 = {
      common_config_value = "       你在身边的时间总是过得太快，有时候感觉，你才是掌控时间的人。"
    },
    start_text2 = {
      common_config_value = "       日历上叠加的数字无法承载所有的心绪，好在我们早把彼此写入生命的每一页了。"
    },
    start_text3 = {
      common_config_value = "       你像是乐章上那个唯一跳跃的音符，谱出了最动听的旋律。"
    },
    start_text4 = {
      common_config_value = "       我会全力以赴，不畏困难，摒弃借口，完成陪伴你一生的任务。"
    },
    start_text8 = {
      common_config_value = "       时间久了越来越觉得，和你一起做没意义的事还挺有意义的。"
    }
  },
