    birthday_words = {
      common_config_value = "He was going to enter the model plane competition... and get first place. |I'm going to prove to you that, even without Evol, I'm still just as good. |Why did she still hold out hope when she knew exactly what the result was going to be? |This day doesn't just belong to you. |It belongs to everyone who has prepared for and looked forward to the day for a long time. |Happy birthday, Gav. |You're another year older today. |You'll meet someone who will want to spend your birthday with you for the rest of your life. |Every year from now on, I want us to all spend this day together like this. |Eating cake. Chatting. And singing happy birthday. Together."
