  [100001] = {
    Scenic_story_min_guarantee = {common_config_value = "4"},
    Scenic_story_probability = {common_config_value = "2500"},
    Summer_Palace_H5link = {common_config_value = "102014"},
    Summer_Palace_begin_role_story = {
      common_config_value = "811311|811321|811331|811341|811381"
    },
    Summer_Palace_begin_story = {common_config_value = "811301"},
    Summer_Palace_card_id = {
      common_config_value = "1:31740|2:32740|3:33760|4:34770|8:38210"
    },
    Summer_Palace_choose_dialogue_1 = {
      common_config_value = "除了想去商店买冰激凌外，想好下个景点去哪了吗？|虽然景色好看，但也要好好看路。|对着导览册冥思苦想这么久，又有什么新发现了？"
    },
    Summer_Palace_choose_dialogue_2 = {
      common_config_value = "看你期待的样子，应该是想好下个景点去哪儿了。|嗯，北方的秋景确实有种独特的美。|听说傍晚的湖边景色很不错，我们可以过去欣赏。"
    },
    Summer_Palace_choose_dialogue_3 = {
      common_config_value = "这里值得逛的景点太多啦！去哪个好呢……|不用着急，我们可以在园内慢慢地逛~|和薯片小姐一起逛颐和园，果然和想象中一样开心！"
    },
    Summer_Palace_choose_dialogue_4 = {
      common_config_value = "怎么突然停下了，接下来想去哪？|今天的天气不错，风吹来很凉爽。|累了吗？我们在长椅上休息一下。"
    },
    Summer_Palace_choose_dialogue_8 = {
      common_config_value = "怎么考虑这么久，下一个景点想去哪儿？|前面好像有个小卖部，不知道有没有怀旧冷饮。|把园区都转一遍，今天你一定是朋友圈步数之王。"
    },
    Summer_Palace_consume = {
      common_config_value = "119624,101,1"
    },
    Summer_Palace_end_role_story = {
      common_config_value = "811317|811327|811337|811347|811387"
    },
    Summer_Palace_free_items = {
      common_config_value = "119624,101,5"
    },
    Summer_Palace_scenic_reward = {
      common_config_value = "119625,101,5"
    },
    Summer_Palace_visit_reward = {
      common_config_value = "119625,101,2|2500:119625,101,3|5000:119625,101,4|2500"
    },
    Summer_Palace_visited_dialogue_1 = {
      common_config_value = "这里刚才已经来过了，换一个吧。"
    },
    Summer_Palace_visited_dialogue_2 = {
      common_config_value = "好像已经去过这个景点了，再看看其他地方呢？"
    },
    Summer_Palace_visited_dialogue_3 = {
      common_config_value = "薯片小姐忘了吗？这里我们刚刚来过哦。"
    },
    Summer_Palace_visited_dialogue_4 = {
      common_config_value = "这里我们刚才来过，有其他想去的地方吗？"
    },
    Summer_Palace_visited_dialogue_8 = {
      common_config_value = "这就要二刷了？还是去个我们没到过的景点吧。"
    },
    activity_show_delay = {common_config_value = "172800"},
