    Summer_Palace_choose_dialogue_1 = {
      common_config_value = "想好下一个地方去哪了吗？|虽然这里对某人来说很新奇，但也要好好看路。|又有什么新发现了？"
    },
    Summer_Palace_choose_dialogue_2 = {
      common_config_value = "看你期待的样子，应该是想好下一步去哪儿了？|嗯…这个游乐园里的景点，似乎都很“别具一格”。|我发现了一片好看的湖景，等会可以一起过去欣赏。"
    },
    Summer_Palace_choose_dialogue_3 = {
      common_config_value = "这里值得逛的地方太多啦！我们要全部都打卡！|不用着急，我们可以边逛乐园边寻找线索~|只要是和薯片小姐一起，去哪里都很开心！"
