    Summer_Palace_choose_dialogue_4 = {
      common_config_value = "怎么突然停下了，接下来准备往哪走？|天气还不错，很适合逛游乐园。|累了吗？我们在长椅上休息一下。"
    },
    Summer_Palace_choose_dialogue_8 = {
      common_config_value = "怎么考虑这么久，等下去哪儿想好了没？|渴了，去饮品摊逛逛吧。|把整个游乐园都转一遍，肯定能找到出去的办法。"
    },
