  [122001] = {
    activity_show_delay = {common_config_value = "172800"},
    dunhuang_after_share_bq = {
      common_config_value = "修复完成的壁画上，出征的军队整装待发，似乎下一秒画上就会传来杀伐之声，向我和白起展示出唐代军人的铁骨与信仰。"
    },
    dunhuang_after_share_lx = {
      common_config_value = "在与凌肖一同修复壁画的过程中，我体会到了壁画背后的历史。这些由前人传承给我们的历史，也将传向更后来的人们。"
    },
    dunhuang_after_share_lzy = {
      common_config_value = "在我和李泽言的共同努力下，壁画一角被成功修复了。看着这幅“飞天壁画”，敦煌那瑰丽神秘的面纱正在徐徐展开。"
    },
    dunhuang_after_share_xm = {
      common_config_value = "我和许墨遇到了一位投身于敦煌壁画临摹的画家。听着他娓娓道来的陈年回忆，我们像乘上了一艘小船，越过历史云烟，驶向心灵净土。"
    },
    dunhuang_after_share_zql = {
      common_config_value = "我与周棋洛一同修复了壁画的一部分，这被历史传承下来的“反弹琵琶”声，将会在现代继续闪光。"
    },
    dunhuang_begin_role_story = {
      common_config_value = "818811|818821|818831|818841|818881"
    },
    dunhuang_blow_button = {common_config_value = "0.6"},
    dunhuang_blow_force = {common_config_value = "15"},
    dunhuang_blow_success = {common_config_value = "0.98"},
    dunhuang_blow_time = {common_config_value = "20"},
    dunhuang_brush_button = {common_config_value = "0.6"},
    dunhuang_brush_success = {common_config_value = "0.98"},
    dunhuang_card_reward = {
      common_config_value = "31990:32970:33990:534010:38390"
    },
    dunhuang_consume_per_time = {
      common_config_value = "400087,101,1"
    },
    dunhuang_end_role_story = {
      common_config_value = "818812|818822|818832|818842|818882"
    },
    dunhuang_fore_share_bq = {
      common_config_value = "我带着白起来到了市博物馆参观敦煌展，顺便为正在筹备的节目踩点。在这里，我和白起一起欣赏到了一场难忘的“千年华彩”。"
    },
    dunhuang_fore_share_lx = {
      common_config_value = "没想到被恋语大学安排来做现场检查的竟然就是凌肖，走到壁画区时，由修复师们亲手复现的壁画似乎令他有些感慨……"
    },
    dunhuang_fore_share_lzy = {
      common_config_value = "正在做导览员的我遇到了突然到场的李泽言，这场奇妙的“敦煌展览”，让我们开启了一段新奇的逛展之旅。"
    },
    dunhuang_fore_share_xm = {
      common_config_value = "我正筹备一场敦煌艺术沉浸展时，许墨忽然造访探班，我便带他体验了身临其境的“敦煌”之旅。"
    },
    dunhuang_fore_share_zql = {
      common_config_value = "与偷偷来探班的周棋洛相约在唐乐的琵琶声中，琵琶声声入耳，带我们重新回到那个瑰丽的时代。"
    },
    dunhuang_relate_share = {
      common_config_value = "17112:17113:17114:17115:17116"
    },
    dunhuang_response_bq = {
      common_config_value = "清理剩下的这点残余，风最擅长。"
    },
    dunhuang_response_lx = {
      common_config_value = "放那儿吧，剩下的我来。"
    },
    dunhuang_response_lzy = {
      common_config_value = "不用这么小心翼翼，剩下的部分我来给你示范。"
    },
    dunhuang_response_xm = {
      common_config_value = "余下的部分，你愿意交由我来完成吗？"
    },
    dunhuang_response_zql = {
      common_config_value = "没关系，剩下部分的就交给我吧！"
    },
    dunhuang_reward_per_day = {
      common_config_value = "400087,101,8"
    },
    dunhuang_reward_per_time_1st = {
      common_config_value = "400088,101,7"
    },
    dunhuang_reward_per_time_2nd = {
      common_config_value = "400088,101,8"
    },
    dunhuang_reward_per_time_quick = {
      common_config_value = "400088,101,5:400088,101,6"
    },
    dunhuang_shop_redpoint = {
      common_config_value = "400088,101,60"
    },
    dunhuang_text_bq_1 = {
      common_config_value = "仪仗队列在整幅壁画的前部，约占全图四分之一的比例，前导骑马横吹四对，鼓角各四人，左右列队。据《唐六典》记载“诸道行军皆给鼓角，万人以上大角六面，大鼓十面。”\n张议潮出行图仪仗部分即是盛唐时期军容的如实反映，也表现出了大军收复河西的雄心壮志。\n|740001"
    },
    dunhuang_text_bq_2 = {
      common_config_value = "张议潮在收复河西的过程中，屡次派使求授旌节，图上所画门旗、信幡、旌节正是对唐代旌节制度的形象绘制。\n旗幡随风而动，延绵浩荡，似比云霓更夺目，彰显出肃穆的气氛，仿佛让人身临其境，亲眼看到大军出征的那一刻。\n|740002"
    },
    dunhuang_text_bq_3 = {
      common_config_value = "张议潮穿着圆领红袍，系革带，着幞头，骑白马，执短鞭。为了彰显他身份的高贵，壁画中他本人的形体比其他人高大许多，很容易成为视觉的焦点。\n张议潮统军出行抗击吐蕃，收复河西的雄壮气势，也通过工匠的描摹，永远地留在了他曾纵马走过的这一片黄沙之中。\n|740003"
    },
    dunhuang_text_bq_4 = {
      common_config_value = "壁画里的驮运部分是最为生动奔放的。一人策马追赶前面奔跑的猎物，后面十多位骑马者正在相互交谈，或回头，或侧身。其后的两位骑马者正在向后方呼唤队伍尾部的四匹空鞍马。画中马匹骆驼的颜色有黑、白、橘黄等几种颜色，更具有真实感与生动感，为画面灌注了不少生气。\n|740004"
    },
    dunhuang_text_bq_5 = {
      common_config_value = "壁画所用色彩华丽，山水与树木多用石绿色点染，人物坐骑多用红、赭、白等色渲染，河流天空以蓝色绘制，整体色彩和谐干净，深浅错落有致。\n除此之外，更是在绚烂而古朴的颜色中重现当年山水，以浓墨重彩令人梦回盛唐。\n|740005"
    },
    dunhuang_text_lx_1 = {
      common_config_value = "莫高窟初唐第323窟，是敦煌石窟中较为特殊的一部分，是仅存的以佛教史迹为主题内容的一窟，《张骞出使西域图》便是其中最具代表性的一幅。\n其将原本属于政治外交性质的张骞出使西域事件，经艺术加工成了佛像初入汉地的故事性壁画。\n|780001"
    },
    dunhuang_text_lx_2 = {
      common_config_value = "此壁画由多个场景构成，情节由右至左，呈凹形走向，并用山峦图像把故事分割开。\n画面下部，画有一人跪倒在地，向骑在马上的人行礼。跪地行礼的便是张骞，而他行礼的对象则是当时的皇帝汉武帝，这部分壁画真实地记录了张骞辞别汉武帝，出使西域的场景。\n而壁画中的其他部分，则有艺术加工的成分，绘述了汉武帝供奉佛像，以及张骞行至西域求佛法的过程。\n|780002"
    },
    dunhuang_text_lx_3 = {
      common_config_value = "张骞出使西域原本是奉汉武帝的皇命，实现联合大月氏抗击匈奴的军事意图。\n其出使西域后，影响远超军事范围，深刻促进了汉夷文化交流，中原文明通过张骞开辟的这条“丝绸之路”迅速向四周传播，促进了世界文化的交流与繁荣。\n张骞出使，也成为了中国古代历史上影响深远的对外交往活动之一。\n|780003"
    },
    dunhuang_text_lx_4 = {
      common_config_value = "张骞出使西域虽然并未实现联合大月氏合击匈奴的军事目标，但带回了自己绘制的西域各部地图和各种所闻所见、社会风貌知识。更重要的是，张骞还带回了关于匈奴军队的详细情报，这也协助汉军西征最终取胜，开疆扩土。\n可以说，现代中国的领土广袤，汉武帝与张骞功不可没。\n|780005"
    },
    dunhuang_text_lx_5 = {
      common_config_value = "绘制《张骞出使西域》的初唐时期，正是道居佛先、佛道之争不息的时代。\n佛教信众借张骞把佛教传入中国的事件提早了两百多年，以此与道教的“老子化胡”——即宣称“老子西行转生为释迦佛”的说法相抗衡。\n当时的敦煌人正是以这种虚实相交的手法，勾画出佛教在中国传播的历史。\n|780004"
    },
    dunhuang_text_lzy_1 = {
      common_config_value = "几身飞天在主尊阿弥陀佛的华盖上方，是莫高窟唐代飞天的代表作之一。\n飞天们一前一后分成两列，对称地拥护在华盖的左右两侧，手中一边接引，一边撒花，伴随着空中荡漾的飘带，颇有灵动美妙的风采。\n|710001"
    },
    dunhuang_text_lzy_2 = {
      common_config_value = "壁画修复是一场同时间赛跑的艰苦工作。\n面对类似空鼓、起甲之类的病害，尚能借助现有的手段修缮，壁画最大的对手是不断延伸的时间。\n那些原本由矿物提供的明艳色彩，经由时光侵蚀，在氧化反应下渐渐褪去光泽，只留下黯淡的躯壳。\n只有经过一代代壁画修复师的不断努力，才能让这些壁画重现往日的色彩。\n|710004"
    },
    dunhuang_text_lzy_3 = {
      common_config_value = "飞天的形态多样，历朝历代都有不同的变化，比如西魏的蓝裙飞天，隋代的黑飞天。\n可最让人印象深刻的，当属唐代飞天。盛唐时期国力强盛，与外商互通更为紧密，不断交织的文化使得此时的壁画更具融合性。\n而唐代的审美趋向也让此时的飞天大都体态雍容、衣饰华贵。艳丽的色彩和颇具现代感的审美取向，很容易脑补出“大唐盛世”这几个字。\n|710003"
    },
    dunhuang_text_lzy_4 = {
      common_config_value = "飞天是敦煌壁画的标志和象征，大都以能歌善舞的神仙形象出现在壁画中。\n不过最早的飞天概念是来自于古印度的香神和歌神，后经时代演变，具体的人物不再作为壁画的主体出现，职责也逐渐多样起来。\n但令人意外的是，如此广泛流传的飞天其实更多以配角的形象出现，在壁画上方起到装饰和烘托氛围的作用。\n|710002"
    },
    dunhuang_text_lzy_5 = {
      common_config_value = "敦煌壁画中蕴含着超乎想象的技巧。\n开凿过的洞窟内只有微弱的烛光，工匠们凭借着微弱的光线和镜片的折射，将手上研磨过的矿物涂抹在红土墙面上。\n细细的云母混杂的白色颜料向四周晕染扩散，壁画中人物的眉宇发梢便被不断晕染开来，形成独特的粗犷轮廓。\n|710005"
    },
    dunhuang_text_xm_1 = {
      common_config_value = "狩猎图所在的莫高窟第 249 窟充斥着中原文化和外来佛教文化的叠影。\n窟顶绘有阿修罗、东王公和西王母等神祇，不乏异兽相随和祥瑞缭绕。狩猎图中的山林野兽位于洞窟下方，相对于顶部的诸神所代表的“天”，它则对应为“地”，亦或“人间”。\n整个洞窟构成一个天界和人间共存的独特宇宙，令人遐想联翩。\n|720003"
    },
    dunhuang_text_xm_2 = {
      common_config_value = "狩猎图诞生于一个画匠们对大自然格外钟情的时期。\n彼时，画匠们忘情山水，寄情山林。狩猎图中，猎者、猛虎和野鹿一同置身的连绵远山，呈现出重峦叠嶂、风烟俱净、天山共色的美景。\n虽然此时的山林画尚很稚拙，但画面里却处处流淌着“青山人独处，飞鸟显寂静”的气息。\n|720004"
    },
    dunhuang_text_xm_3 = {
      common_config_value = "狩猎图的写意笔触将西北的苍凉劲逸挥洒无疑，而大胆鲜明的色彩则和敦煌洞窟的整体艺术风格相得益彰。\n画中山水用石青石绿、黑白相间隔，绵延的山坡铺上渐次新绿，浓淡有致。山间绘有红色的树丛枝干，葱茏润泽。而穿行于山林里的动物大多用红色平涂，略加渲染。两名猎人分别为黑衣红马与红衣黑马，相映成趣。\n|720002"
    },
    dunhuang_text_xm_4 = {
      common_config_value = "早在千年前的敦煌，画匠已经开始用画笔描绘动物的故事，以此和猎捕、屠宰等伤害动物的行为相抗。\n《狩猎图》诞生于西魏，这时候的敦煌动物画正在迎来辉煌时期，造型渐渐向现实靠拢，风格变得自由灵动。在狩猎图截取的画框外，左侧有一只被狩猎惊扰的野牛正慌乱奔逃，右侧则有浑然不知前方危险的猪群正在从容漫步。\n它们的呼吸和心跳，无一不传出天地间野性的呼唤。\n|720001"
    },
    dunhuang_text_xm_5 = {
      common_config_value = "在漫长的文明演进历程中，狩猎题材一直以各种艺术形式为载体，活跃在我国文化遗迹中。在莫高窟狩猎壁画诞生之前，它已经在史前岩画、先秦青铜器和汉画像石等绘画艺术中大量出现。\n而敦煌莫高窟的狩猎图在继承此前的艺术风格之外，更多展现了佛教视角下的大千世界，传递了众生有灵，切莫杀生的观念。\n|720005"
    },
    dunhuang_text_zql_1 = {
      common_config_value = "《反弹琵琶》是敦煌壁画《无量寿经变》的局部系中唐作品，描绘的是伎乐天伴随仙乐翩翩起舞，展现其“反弹琵琶”的绝妙舞姿。\n其人物造型丰腴饱满，线条明快流畅，展现出了伎乐天的纤纤神韵；以石绿色、赭黄、铅白为主的用色更显得画面典雅自然。技法高绝，是敦煌壁画的代表性作品之一。\n|730001"
    },
    dunhuang_text_zql_2 = {
      common_config_value = "伎乐天是佛教中的香音之神，能歌善舞，是佛及菩萨的侍从，职能是“娱佛”。\n在敦煌壁画中的伎乐天亦指在天宫奏乐的乐伎，常以“飞天”的形象出现，他们或手持贡物，或是带着各种乐器，表示以美妙的音声来赞美佛、供养佛。\n|730004"
    },
    dunhuang_text_zql_3 = {
      common_config_value = "如果说有一个姿势能够成就飞天，那就非反弹琵琶莫属了。\n即便按照当时的制式，琵琶的重量较轻，但如壁画中将琵琶高举到颈后的姿势是很难正常进行演奏的，以这样“叛逆”的动作舞乐，从中也可以看出盛唐时期开放自由的时代风貌。\n|730003"
    },
    dunhuang_text_zql_4 = {
      common_config_value = "“反弹琵琶”壁画中弹奏的主要乐器——琵琶，早在南北朝时，其原型“曲项琵琶”便通过丝绸之路从波斯经如今的新疆地区传入我国。\n在隋唐的九部、十部乐中，曲项琵琶已成为主要乐器，对盛唐的歌舞文化产生了重要影响。\n从敦煌壁画中也可看出琵琶在当时乐队中的重要性。\n|730002"
    },
    dunhuang_text_zql_5 = {
      common_config_value = "从历朝历代的壁画艺术中，可以窥见当时的时代风骨。\n盛唐开放包容，因此在乐舞壁画中常见关内的传统乐器与外来乐器同奏，舞者着装并不似传统般保守，舞姿线条也更为多元丰富。\n这一点并不仅仅体现在“反弹琵琶”这一代表性舞姿中，更体现在唐代壁画的每一个角落。\n|730005"
    },
    dunhuang_tips_start_time = {common_config_value = "5"}
  },
