    board_response_1 = {
      common_config_value = "既然想看风景，就安安静静待在我旁边，别到处乱跑。|又发现什么“看起来超级无敌好吃”的小吃摊了？|觉得冷就把手放进我口袋里来。:不用想都知道，等下笨蛋肯定会嚷着要去喂锦鲤。|电影节办得不错，明年可以考虑赞助。"
    },
    board_response_2 = {
      common_config_value = "想好要去哪了吗？这里每个角落都值得细细品味。|每次路过这些老房子，都能发现新的有趣之处。|这里的风景最好，我特意留到现在带你来。:古镇的时光总是格外慢，正好可以让我有时间，一直看着你。|看来我们选对了落脚点，阳光正好。"
    },
    board_response_3 = {
      common_config_value = "小镇最全攻略都记在我的脑袋里了，就放心跟我走吧~|想去哪就去哪，银子管够！|累了吗？我们找个好风景去休息休息吧。:好的风景，一定要多多拍照多多留念~|这里比影视城还棒，下次是不是能来这儿拍电影？"
    },
    board_response_4 = {
      common_config_value = "已经准备好了？那我们出发。|放心，我把小镇地图记住了，不论哪里都能带你过去。|想摸摸我头上的揪揪？……可以。:这次带什么纪念品回家呢？|就这么看一看风景也很好。"
    },
    board_response_8 = {
      common_config_value = "打算去哪儿溜达？|这里的建筑都挺合规制，不错。|几百年前的西月街，应该就是这副模样。:突然感觉，和你这样悠闲地无所事事也挺不错。|我觉得你手上缺了一把油纸伞。"
    },
    board_response_npc = {
